begin;
set local s1.tap='off';
\ir s3_fixture.sql
set local role authenticated;
select pg_temp.as_user('10000003-0000-4000-8000-000000000003');
select pg_temp.check((public.preview_room_invite_v1('ZZZZZZ')->>'reason')='INVITE_UNAVAILABLE','unknown code response is uniform') from generate_series(1,4);
select pg_temp.check((public.preview_room_invite_v1('ZZZZZZ')->>'reason')='INVITE_RATE_LIMITED','fifth failed lookup commits a lock envelope');
select pg_temp.check((public.preview_room_invite_v1('ABCDEF')->>'reason')='INVITE_RATE_LIMITED','changing codes cannot bypass actor lock');
select pg_temp.check(public.join_room_by_code('ABCDEF') is null,'legacy code join returns committed NULL while locked');
reset role;
select pg_temp.check((select failure_count=5 from private.s3_invite_limits where actor_id='10000003-0000-4000-8000-000000000003'),'failed attempts persisted rather than exception rollback');
set local role authenticated;
select pg_temp.as_user('10000004-0000-4000-8000-000000000004');
insert into s4_data values('preview',public.preview_room_invite_v1((select v->>'code' from s4_data where k='s3_created')));
select pg_temp.check((select v->>'outcome'='preview' and not v ?| array['room_id','owner_id','members','location','health','account'] from s4_data where k='preview'),'preview discloses only minimal projection');
select pg_temp.check((select (v->>'member_count')::integer=2 from s4_data where k='preview'),'preview member count excludes NULL display-only rows');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.get_room_lifecycle_v1(pg_temp.s3_room())$q$)='42501','preview does not grant membership');
select pg_temp.check((public.join_room_invite_v1((select (v->>'preview_id')::uuid from s4_data where k='preview'),gen_random_uuid())->>'outcome')='applied','explicit preview confirmation joins room');
reset role;
insert into public.follows(follower_id,following_id,role) values('10000001-0000-4000-8000-000000000001','10000005-0000-4000-8000-000000000005','mate') on conflict do nothing;
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('target_invitation',to_jsonb(public.create_room_invitation(pg_temp.s3_room(),'10000005-0000-4000-8000-000000000005')));
reset role;
select pg_temp.check((select expires_at<=created_at+interval '7 days' from public.room_invitations where id=(select (v#>>'{}')::uuid from s4_data where k='target_invitation')),'target invitation has independent bounded TTL');
update private.s3_invite_codes set issued_at=issued_at-interval '2 minutes',expires_at=expires_at-interval '2 minutes' where room_id=pg_temp.s3_room();
set local role authenticated;
select public.rotate_room_invite_code_v1(pg_temp.s3_room(),pg_temp.s3_rev(),gen_random_uuid());
select pg_temp.check((select status='pending' from public.room_invitations where id=(select (v#>>'{}')::uuid from s4_data where k='target_invitation')),'code rotation does not cancel independently targeted invitation');
select pg_temp.as_user('10000005-0000-4000-8000-000000000005');
select pg_temp.check(public.accept_room_invitation((select (v#>>'{}')::uuid from s4_data where k='target_invitation'))=pg_temp.s3_room(),'target may explicitly accept invitation after code rotation');
select pg_temp.check(public.accept_room_invitation((select (v#>>'{}')::uuid from s4_data where k='target_invitation'))=pg_temp.s3_room(),'accepted invitation replays only while target remains a member');
select public.leave_room_member_v1(pg_temp.s3_room(),pg_temp.s3_rev(),gen_random_uuid());
select pg_temp.check(public.accept_room_invitation((select (v#>>'{}')::uuid from s4_data where k='target_invitation')) is null,'accepted invitation cannot readmit a departed target');
reset role;
update private.s3_invite_limits set failure_count=0,failure_window=clock_timestamp(),minute_window=clock_timestamp(),minute_count=0,day_window=clock_timestamp(),day_count=0,lock_until=null where actor_id='10000004-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.as_user('10000004-0000-4000-8000-000000000004');
select pg_temp.check(bool_and(public.preview_room_invite_v1(public.get_room_lifecycle_v1(pg_temp.s3_room())->'invite'->>'code')->>'outcome'='preview'),'thirty successful lookups share one minute allowance') from generate_series(1,30);
select pg_temp.check(public.preview_room_invite_v1(public.get_room_lifecycle_v1(pg_temp.s3_room())->'invite'->>'code')->>'reason'='INVITE_RATE_LIMITED','thirty-first successful-code lookup is rate limited');
reset role;
update private.s3_invite_limits set minute_window=clock_timestamp()-interval '61 seconds',day_count=199 where actor_id='10000004-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.check(public.preview_room_invite_v1(public.get_room_lifecycle_v1(pg_temp.s3_room())->'invite'->>'code')->>'outcome'='preview','new minute permits the two-hundredth daily request');
select pg_temp.check(public.preview_room_invite_v1(public.get_room_lifecycle_v1(pg_temp.s3_room())->'invite'->>'code')->>'reason'='INVITE_RATE_LIMITED','two-hundred-and-first request cannot reset daily allowance');
reset role;
select pg_temp.check((select day_count=200 and minute_count=1 from private.s3_invite_limits where actor_id='10000004-0000-4000-8000-000000000004'),'success preserves exact daily total across minute resets');
update private.s3_invite_limits set failure_window=clock_timestamp()-interval '16 minutes',lock_until=clock_timestamp()-interval '1 second' where actor_id='10000003-0000-4000-8000-000000000003';
set local role authenticated;
select pg_temp.as_user('10000003-0000-4000-8000-000000000003');
select pg_temp.check(public.preview_room_invite_v1('ZZZZZZ')->>'reason'='INVITE_UNAVAILABLE','expired failure window releases actor lock');
reset role;
select pg_temp.check((select failure_count=1 from private.s3_invite_limits where actor_id='10000003-0000-4000-8000-000000000003'),'only elapsed failure window resets failure count');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.rotate_room_invite_code_v1(pg_temp.s3_room(),pg_temp.s3_rev(),gen_random_uuid())$q$)='S3005','second rotation in a minute is denied');
reset role;
update private.s3_invite_codes set issued_at=issued_at-interval '2 minutes',expires_at=expires_at-interval '2 minutes' where room_id=pg_temp.s3_room();
insert into private.s3_invite_codes(room_id,generation,code_digest,issued_at,expires_at,retired_at)
 select pg_temp.s3_room(),n,private.s3_code_digest('synthetic-retired-'||n),clock_timestamp()-interval '2 minutes',clock_timestamp()+interval '6 days',clock_timestamp()-interval '1 minute' from generate_series(3,11) n;
set local role authenticated;
select pg_temp.check(pg_temp.sqlstate_of($q$select public.rotate_room_invite_code_v1(pg_temp.s3_room(),pg_temp.s3_rev(),gen_random_uuid())$q$)='S3005','eleventh rotation per day is denied independently of minute window');
rollback;
